translations["ruRU"] = {
    ["TIP_HOME_COMMANDS"] = "Настройка: Команды: /kr - окно; /kr test - тестовая панель; /kr lock - перемещение.. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_HOME_QUICK_TITLE"] = "Настройка: Быстрые настройки. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_HOME_QUICK_NOTE"] = "Настройка: Это настройки на будущее: движок ротаций пока не реализован.. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_HOME_ENABLE_RECOMMENDATIONS"] = "Настройка: Включить будущие рекомендации. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_DISPLAY_SHOW_PANEL"] = "Настройка: Разрешить показ панели. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_DISPLAY_TEST_MODE"] = "Настройка: Показать тестовые иконки. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_DISPLAY_PANEL_LOCK"] = "Настройка: Заблокировать перемещение. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_HOME_GO_DISPLAY"] = "Настройка: Настройки отображения. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
