    ["TIP_ADV_PENDING_COUNT"] = "Настройка: Отложено до окончания боя: %d. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_ADV_CONFIRM_APPEARANCE"] = "Настройка: Вернуть оформление Classic?. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_ADV_CONFIRM_BRANCH"] = "Настройка: Сбросить настройки ротации текущей ветки талантов?. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_ADV_RESET_ALL_CONFIRM"] = "Настройка: Удалить все настройки Kord Rotation и перезагрузить интерфейс?. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_ADV_RESET_APPEARANCE"] = "Настройка: Сбросить оформление. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_ADV_RESET_BRANCH"] = "Настройка: Сбросить текущую ветку. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_ADV_RESET_ALL"] = "Настройка: Сбросить все данные. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_ADV_COMPAT_TITLE"] = "Настройка: Совместимость клиента. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_ADV_COMPAT_NOTE"] = "Настройка: Здесь указаны версия клиента/API и доступ в бою. Частоты движка — настройки на будущее.. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_DIAG_TITLE"] = "Настройка: Диагностика талантов. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_DIAG_API_TITLE"] = "Настройка: Доступность API клиента (+ есть, - нет). Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_DIAG_EVENTS"] = "Настройка: Последние события диагностики. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_DIAG_TEST_UI"] = "Настройка: Проверить панель. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_DIAG_EXPORT_TITLE"] = "Настройка: Диагностический отчёт. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_DIAG_COPY_HELP"] = "Настройка: Выделите текст и нажмите Ctrl+C. Прямой доступ к буферу обмена отсутствует.. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_DIAG_SUMMARY"] = "Настройка: Класс: %s | Профиль: %s | Статус: %s\\\\nОчки: %s | Событие: %s\\\\nСлоты: %d | X: %s Y: %s | Масштаб: %s | Тест: %s. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_UI_ENABLED"] = "Настройка: ВКЛ. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_UI_DISABLED"] = "Настройка: ВЫКЛ. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_DIAG_DETAILS"] = "Настройка: Конфиг: %s | Ветка: %s | Метод: %s | Уверенность: %s. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_DIAG_RESCAN"] = "Настройка: Перечитать таланты. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_DIAG_CLEAR"] = "Настройка: Очистить журнал. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_DIAG_SELECT"] = "Настройка: Выделить отчёт. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["TIP_UI_TIP_NOTE"] = "Настройка: Параметр интерфейса; боевые рекомендации пока не работают.. Этот параметр управляет указанной функцией интерфейса. Изменения сохраняются; боевые рекомендации пока не работают.",
    ["ADV_LANG_DE"] = "Deutsch",
    ["ADV_LANG_FR"] = "Français",
    ["ADV_LANG_ES"] = "Español",
    ["ADV_LANG_PT"] = "Português (Brasil)",
    ["TIP_ROT_SAVE_RESOURCES"] = "Экономия классового ресурса: маны, энергии, ярости, концентрации, силы рун и т. п. В будущем ротация будет стараться не тратить ресурс на второстепенные способности, если он нужен для более важного действия. Сейчас это сохранённое предпочтение; боевой движок ещё не активен.",
    ["TIP_IND_HIGHLIGHT_ENABLE"] = "Подсветка кнопок способностей на стандартных панелях действий WoW: в будущем она будет указывать, какую способность рекомендует ротация. Это не подсветка иконок в окне настроек. Пока функция не подключена к боевому движку.",
    ["TIP_IND_HIGHLIGHT_STYLE"] = "Рамка — цветной контур вокруг кнопки способности. Свечение — заметный светящийся эффект вокруг неё. Это выбор будущего эффекта на панелях действий, сейчас он только сохраняется.",
    ["TIP_IND_HIGHLIGHT_COUNT"] = "Первая — выделять только основную рекомендованную способность. Несколько — показывать несколько следующих рекомендаций, если движок это поддержит. Пока рекомендации не рассчитываются.",
    ["TIP_IND_HIGHLIGHT_STRENGTH"] = "Интенсивность будущей подсветки кнопок: меньшее значение означает более слабый визуальный эффект, большее — более заметный. Сейчас настройка сохраняется без боевого эффекта.",
    ["TIP_STYLE_HIGHLIGHT"] = "Выделяет главную иконку именно в тестовой панели Kord Rotation цветной рамкой. Не включает подсветку кнопок стандартной панели WoW.",
    ["TIP_STYLE_BACKGROUND_ALPHA"] = "Непрозрачность фона под иконкой: 0% — полностью прозрачный фон, 100% — полностью непрозрачный. Меняйте ползунком или вводите число 0–100 вручную и нажимайте Enter.",
    ["TIP_IND_DEFENSIVE_ENABLE"] = "Показывать отдельные тестовые слоты защитных способностей. Защитные способности уменьшают получаемый урон или помогают выжить. Сейчас показывается только макет без автоматического выбора заклинания.",
    ["TIP_IND_INTERRUPT_ENABLE"] = "Отдельная тестовая иконка для прерывания вражеского заклинания. Прерывание останавливает каст противника. Автоматический поиск кастов и рекомендации пока не работают.",
    ["TIP_IND_SOUND_ENABLE"] = "Общий переключатель будущих звуковых уведомлений ротации. Пока работает только отдельная кнопка ручного теста звука; автоматические уведомления отсутствуют.",
    ["TIP_ROT_ONLY_COMBAT"] = "В будущем ограничивает рекомендации долгих атакующих кулдаунов моментами, когда персонаж находится в бою. Сейчас параметр лишь сохраняется.",
    ["TIP_ROT_PREBUFFS"] = "Предварительные усиления — положительные эффекты (баффы), которые персонаж применяет перед началом боя. Эта настройка предназначена для будущих рекомендаций и пока не исполняет заклинания.",
    ["TIP_IND_DEFENSIVE_COMBAT"] = "Показывать будущие защитные рекомендации только в бою. Тестовые иконки остаются демонстрацией интерфейса.",
    ["TIP_IND_INTERRUPT_TEXT"] = "Показывать поясняющий текст возле будущего индикатора прерывания. Сейчас активен только тестовый макет.",
    ["TIP_IND_INTERRUPT_SOUND"] = "Предпочтение звукового сигнала при будущем обнаружении прерываемого каста врага. Сейчас автоматических сигналов нет.",
    ["TIP_ADV_MINIMAP"] = "Показывает кнопку Kord Rotation у миникарты. Левый клик открывает настройки, правый — вкладку «Дополнительно».",
    ["TIP_ADV_TOOLTIPS"] = "Показывает подробные пояснения при наведении на строки настроек: что меняется, как работает функция и доступна ли она в текущей версии.",
