    ["TIP_HOME_COMMANDS"] = "Einstellung: Befehle: /kr - Fenster; /kr test - Testleiste; /kr lock - verschieben/sperren.. Diese Option steuert die angegebene Oberflächenfunktion. Änderungen werden gespeichert; Kampfempfehlungen sind noch nicht aktiv.",
